import os
import subprocess
import tempfile
from flask import Flask, request, jsonify

app = Flask(__name__)

TEMPLATE_DIR = '/opt/reports/templates'

def sanitize_filename(name):
    """Remove directory traversal attempts but allow template names with dots."""
    # Strip leading/trailing whitespace
    name = name.strip()
    # Block null bytes
    if '\x00' in name:
        raise ValueError('Invalid filename')
    # Collapse multiple dots but allow single dots for extensions
    while '..' in name:
        name = name.replace('..', '.')
    return name

def render_report(template_name, output_format, params):
    """Render a report using system wkhtmltopdf or pandoc."""
    template_path = os.path.join(TEMPLATE_DIR, template_name)

    if not os.path.exists(template_path):
        raise FileNotFoundError(f'Template {template_name} not found')

    with open(template_path, 'r') as f:
        template_content = f.read()

    # Substitute parameters into template
    for key, value in params.items():
        template_content = template_content.replace('{{' + key + '}}', str(value))

    # Write rendered template to temp file
    with tempfile.NamedTemporaryFile(mode='w', suffix='.html', delete=False) as tmp:
        tmp.write(template_content)
        tmp_path = tmp.name

    output_path = tempfile.mktemp(suffix=f'.{output_format}')

    if output_format == 'pdf':
        cmd = f'wkhtmltopdf {tmp_path} {output_path}'
    elif output_format == 'docx':
        cmd = f'pandoc {tmp_path} -o {output_path}'
    else:
        cmd = f'cp {tmp_path} {output_path}'

    # Execute rendering command
    result = subprocess.run(cmd, shell=True, capture_output=True, timeout=30)

    os.unlink(tmp_path)

    if result.returncode != 0:
        raise RuntimeError(f'Render failed: {result.stderr.decode()}')

    return output_path

@app.route('/api/v2/reports/generate', methods=['POST'])
def generate_report():
    """Generate a report from a template with user-supplied parameters."""
    data = request.get_json()

    if not data or 'template' not in data:
        return jsonify({'error': 'template field required'}), 400

    template_name = data['template']
    output_format = data.get('format', 'pdf')
    params = data.get('params', {})

    # Validate output format
    if output_format not in ('pdf', 'docx', 'html'):
        return jsonify({'error': 'Invalid format'}), 400

    try:
        template_name = sanitize_filename(template_name)
    except ValueError as e:
        return jsonify({'error': str(e)}), 400

    try:
        output_path = render_report(template_name, output_format, params)
        return jsonify({'status': 'success', 'path': output_path})
    except FileNotFoundError as e:
        return jsonify({'error': str(e)}), 404
    except Exception as e:
        return jsonify({'error': f'Generation failed: {str(e)}'}), 500

@app.route('/api/v2/reports/preview', methods=['POST'])
def preview_report():
    """Preview a report - renders to HTML only."""
    data = request.get_json()

    if not data or 'template' not in data:
        return jsonify({'error': 'template field required'}), 400

    template_name = data['template']
    params = data.get('params', {})

    try:
        template_name = sanitize_filename(template_name)
    except ValueError as e:
        return jsonify({'error': str(e)}), 400

    try:
        output_path = render_report(template_name, 'html', params)
        with open(output_path, 'r') as f:
            content = f.read()
        os.unlink(output_path)
        return jsonify({'status': 'success', 'html': content})
    except FileNotFoundError as e:
        return jsonify({'error': str(e)}), 404
    except Exception as e:
        return jsonify({'error': f'Preview failed: {str(e)}'}), 500

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
